(ROOT / 'concepts.json').write_text(json.dumps(apps, ensure_ascii=False, indent=2))
with (ROOT / 'taglines.csv').open('w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['App', 'Area', 'Year level', 'Direction', 'Direction name', 'Tagline', 'Visual direction', 'Logo concept', 'Screenshot', 'Logo'])
    for a in apps:
        for d in a['directions']:
            writer.writerow([a['name'], a['area'], a['years'], d['number'], d['title'], d['tagline'], d['style'], d['logo'], d['folder']+'/screenshot.png', d['folder']+'/logo.png'])
print(f'Created {len(apps)} apps and {sum(len(a["directions"]) for a in apps)} directions')
